import{_ as t,o as l,c as e,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"From ISCSI to NVMe-of- A Comparative Look on Storage Protocol Advantages & Challenges - A. Muthmann","description":"","frontmatter":{"title":"From ISCSI to NVMe-of- A Comparative Look on Storage Protocol Advantages & Challenges - A. Muthmann","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Storage Protocols","NVMe-oF","iSCSI","Block Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/From_ISCSI_to_NVMe-of_-_A_Comparative_Look_on_Storage_Protocol_Advantages_Challenges_-_A._Muthmann.md","filePath":"posts/2025/From_ISCSI_to_NVMe-of_-_A_Comparative_Look_on_Storage_Protocol_Advantages_Challenges_-_A._Muthmann.md","lastUpdated":1780459816000}'),r={name:"posts/2025/From_ISCSI_to_NVMe-of_-_A_Comparative_Look_on_Storage_Protocol_Advantages_Challenges_-_A._Muthmann.md"};function i(s,o,a,_,g,p){return l(),e("div",null,[...o[0]||(o[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: Ceph中的块存储协议比较：从iSCSI到NVMe-oF</p><p><strong>主讲人</strong>: Andy Muthmann，CRO公司管理总监</p><p><strong>会议内容</strong>:</p><ol><li><p><strong>公司介绍</strong>:</p><ul><li>CRO公司成立于2017年，总部位于德国，专注于Ceph的部署和管理软件，提供咨询、专业服务、支持和培训等服务。</li><li>CRO公司是Ceph基金会的创始成员之一，积极参与Ceph的开发。</li></ul></li><li><p><strong>会议主题</strong>:</p><ul><li>讨论Ceph中的块存储协议，主要比较RBD、iSCSI和NVMe-oF的优缺点。</li><li>介绍这些协议的历史、性能、可靠性、可扩展性等方面的比较。</li></ul></li><li><p><strong>协议介绍</strong>:</p><ul><li><strong>RBD</strong>: Ceph原生的块存储协议，支持精简配置、快照、克隆和复制，广泛用于虚拟化、容器和私有云环境。</li><li><strong>iSCSI</strong>: 行业标准的块存储协议，已进入维护模式。</li><li><strong>NVMe-oF</strong>: 最新的协议，支持高性能网络，如RDMA、InfiniBand，集成到Ceph中。</li></ul></li><li><p><strong>协议比较</strong>:</p><ul><li><strong>部署复杂性</strong>: RBD最简单，iSCSI和NVMe-oF需要额外的网关和配置。</li><li><strong>网络设置</strong>: RBD使用标准TCP/IP，iSCSI支持多路径，NVMe-oF支持RDMA和多路径。</li><li><strong>性能</strong>: RBD性能最佳，NVMe-oF次之，iSCSI最差。</li><li><strong>可靠性</strong>: RBD依赖Ceph的高可靠性，iSCSI和NVMe-oF需要集群网关来实现高可用性。</li><li><strong>成本</strong>: RBD成本最低，iSCSI和NVMe-oF可能需要额外的硬件和网络支持。</li><li><strong>安全性</strong>: iSCSI缺乏传输加密，需要额外的安全机制。</li></ul></li><li><p><strong>客户反馈</strong>:</p><ul><li>一些客户已从iSCSI迁移到NVMe-oF，整体满意度较高，性能有所提升。</li><li>迁移速度较慢，部分客户受限于vSphere版本，无法及时升级。</li><li>部分客户考虑迁移到其他虚拟化环境，而非继续使用VMware。</li></ul></li><li><p><strong>结论</strong>:</p><ul><li>没有一种协议适合所有场景，选择取决于具体环境、预算和需求。</li><li>通常推荐RBD，因其简单、可靠且性能良好。</li><li>尽量避免使用iSCSI，因其已进入维护模式。</li><li>NVMe-oF是一个现代化的选择，但目前采用率较低。</li></ul></li></ol><p><strong>后续行动计划</strong>:</p><ul><li>继续关注Ceph的新版本，特别是与高可用性和部署相关的改进。</li><li>与客户合作，帮助他们根据具体需求选择合适的块存储协议。</li></ul><p><strong>会议结束</strong>:</p><ul><li>主讲人感谢大家的参与，并鼓励大家继续关注Ceph的发展。</li></ul><p><strong>会议时间</strong>: 未知</p><p><strong>会议地点</strong>: 线上会议</p><p><strong>参会人员</strong>: CRO公司成员及Ceph社区相关人员</p>',12)])])}const h=t(r,[["render",i]]);export{C as __pageData,h as default};
